<?php $ci=&get_instance(); ?>
<section class="garden-panel"><div class="garden-panel-heading"><div><span class="garden-kicker">FROM INPUTS TO SALEABLE PRODUCTS</span><h2>Nursery production & assembly</h2><p class="garden-muted">Plan → issue materials → grow or assemble → record losses & costs → confirm finished output.</p></div><a href="<?= base_url('garden/materials'); ?>" class="garden-button">Materials & costing →</a></div></section>
<?php if($ci->permissions('production_batches_add') && $ci->permissions('recipes_view') && $ci->permissions('items_view')): ?><details class="garden-card" id="new-production"><summary class="garden-create-summary"><span>+ Plan a production batch</span><small>No stock moves until you start it</small></summary><form method="post" action="<?= base_url('garden/production_create'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="request_key" value="<?= $request_key; ?>"><div class="garden-grid"><label>Batch name<input name="name" maxlength="200" required placeholder="e.g. October flowering pots"></label><label>Materials template<select name="recipe_id" data-garden-select hidden required><option value="">Choose template</option><?php foreach($production_templates as $t): ?><option value="<?= (int)$t->id; ?>"><?= htmlspecialchars($t->name.' · '.$t->output_name); ?></option><?php endforeach; ?></select></label><label>Planned finished units<input type="number" min="1" max="9999999" step="1" name="planned_qty" required></label><label>Stock branch<select name="warehouse_id" data-garden-select hidden required><?php foreach($production_warehouses as $w): ?><option value="<?= (int)$w->id; ?>"><?= htmlspecialchars($w->warehouse_name); ?></option><?php endforeach; ?></select></label><label>Planned start<input type="date" name="scheduled_date" value="<?= date('Y-m-d'); ?>" required></label><label>Expected completion<input type="date" name="expected_date"></label></div><label>Batch instructions<textarea name="notes" id="production-batch-notes" rows="3" maxlength="8000"></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'production-batch-notes']); ?><button class="garden-button">Plan batch</button></form></details><?php endif; ?>
<div class="garden-kanban garden-production-board"><?php foreach(['planned'=>'Planned','in_production'=>'Growing / assembling','ready'=>'Ready for review','completed'=>'Completed','cancelled'=>'Cancelled'] as $status=>$label):$cards=array_filter($production_batches,function($b)use($status){return $b->status===$status;}); ?><section class="garden-kanban-lane"><div class="garden-lane-heading"><span><?= $label; ?></span><b><?= count($cards); ?></b></div><div class="garden-lane-body"><?php foreach($cards as $b): ?><a class="garden-project-tile" href="<?= base_url('garden/production_batch/'.(int)$b->id); ?>"><small><?= htmlspecialchars($b->batch_code); ?></small><h3><?= htmlspecialchars($b->batch_name); ?></h3><p><?= htmlspecialchars($b->output_name); ?></p><span class="garden-pill"><?= $b->kind==='growing'?'Growing':'Assembly'; ?></span><p><?= (int)$b->planned_qty; ?> planned · <?= (int)$b->lost_qty; ?> lost<?php if($status==='completed'): ?> · <?= (int)$b->saleable_qty; ?> saleable<?php endif; ?></p><footer><?= htmlspecialchars($b->expected_date ?: 'No completion date'); ?><?php if($b->unit_cost!==null): ?><strong><?= store_number_format($b->unit_cost); ?> / unit</strong><?php endif; ?></footer></a><?php endforeach; ?><?php if(!$cards): ?><p class="garden-lane-empty">No batches in this stage.</p><?php endif; ?></div></section><?php endforeach; ?></div><p class="garden-muted">Showing the latest 250 batches. Completed output becomes ordinary catalogue stock for POS and your existing Online Store.</p>
